                # A doubled quote inside quotes represents one quote
                if i + 1 < n and line[i + 1] == '"':
                    current.append('"')
                    i += 1  # skip the escaped quote
                else:
                    in_quotes = False
            else:
                in_quotes = True
        elif char == ',' and not in_quotes:
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    fields.append(''.join(current))
    return fields
