from datetime import datetime

_LOG_RE = re.compile(
    r'^(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2},\d{1,3}) \[([A-Za-z]+)\] (.+?): (.*)$'
)

_LEVEL_MAP = {
    'WARNING': 'WARN',
    'WARN': 'WARN',
}


def parse_log(line: str) -> dict:
    m = _LOG_RE.match(line)
    if not m:
        raise ValueError(f'Invalid log line: {line!r}')

    ts_str, level_raw, logger, msg = m.groups()

    try:
        ts = datetime.strptime(ts_str, '%Y-%m-%d %H:%M:%S,%f')
    except ValueError:
        raise ValueError(f'Invalid timestamp: {ts_str!r}')

    level = _LEVEL_MAP.get(level_raw.upper(), level_raw.upper())

    return {
        'ts': ts,
        'level': level,
        'logger': logger,
        'msg': msg,
    }
