def compact(n: int) -> str:
    if n < 1000:
        return str(n)
    units = [('mil', 1000), ('mi', 1_000_000), ('bi', 1_000_000_000)]
    for name, base in units:
        value = n / base
        rounded = round(value, 1)
        integer = int(rounded)
        if rounded == 0:
            continue
        if integer % 10 == 0:
            continue
        decimal = rounded - integer
        if decimal == 0:
            return f"{integer} {name}"
        return f"{integer},{decimal:.1f} {name}"
    return str(n)
