from datetime import date, timedelta

def add_business_days(d: date, n: int, holidays: set[date]) -> date:
    def is_business_day(date_obj: date) -> bool:
        return date_obj.weekday() < 5 and date_obj not in holidays

    if n == 0:
        if is_business_day(d):
            return d
        day = d + timedelta(days=1)
        while not is_business_day(day):
            day += timedelta(days=1)
        return day

    if n > 0:
        day = d + timedelta(days=1)
        count = 0
        while count < n:
            while not is_business_day(day):
                day += timedelta(days=1)
            count += 1
        return day

    # n < 0
    day = d - timedelta(days=1)
    count = 0
    while count < -n:
        while is_business_day(day):
            count += 1
            if count == -n:
                return day
            day -= timedelta(days=1)
        return day
