import re

def compare_versions(a: str, b: str) -> int:
    def parse(v: str):
        v = v.split('+', 1)[0]
        core, _, pre = v.partition('-')
        release = [int(x) for x in core.split('.')]
        pre = pre.split('.') if pre else []
        return release, pre

    ra, pa = parse(a)
    rb, pb = parse(b)

    # Compare release part
    for x, y in zip(ra, rb):
        if x != y:
            return 1 if x > y else -1
    if len(ra) != len(rb):
        return 1 if len(ra) > len(rb) else -1

    # No pre-release on either side
    if not pa and not pb:
        return 0

    # A release is higher than its pre-release
    if not pa:
        return 1
    if not pb:
        return -1

    # Compare pre-release identifiers dot by dot
    for x, y in zip(pa, pb):
        xn, yn = x.isascii() and x.isdigit(), y.isascii() and y.isdigit()
        if xn == yn:
            if xn:
                xi, yi = int(x), int(y)
                if xi != yi:
                    return 1 if xi > yi else -1
            else:
                if x != y:
                    return 1 if x > y else -1
        else:
            # Numeric identifiers have lower precedence than alphanumeric
            return -1 if xn else 1

    # All earlier identifiers equal; shorter list is lower
    return 1 if len(pa) > len(pb) else -1
