def set_ini_value(text: str, section: str, key: str, value: str) -> str:
    lines = text.split('\n')
    result = []
    current_section = None
    found = False

    for line in lines:
        stripped = line.strip()

        if stripped.startswith('[') and stripped.endswith(']'):
            current_section = stripped[1:-1].strip()
            result.append(line)
            continue

        if stripped.startswith(';') or stripped.startswith('#'):
            result.append(line)
            continue

        if '=' in line:
            k, _, _ = line.partition('=')
            if current_section == section and k.strip() == key:
                result.append(f'{key} = {value}')
                found = True
                continue

        result.append(line)

    if not found:
        raise KeyError(f'Key {key!r} not found in section {section!r}')

    return '\n'.join(result)
