def find_Rotations(s):
    n = len(s)
    if n <= 1:
        return n  # a single char or empty string needs no rotation
    # Build prefix function (KMP failure function)
    pi = [0] * n
    for i in range(1, n):
        j = pi[i - 1]
        while j > 0 and s[i] != s[j]:
            j = pi[j - 1]
        if s[i] == s[j]:
            j += 1
        pi[i] = j
    smallest_period = n - pi[n - 1]
    # The smallest period must divide n for a rotation to reproduce the string
    if n % smallest_period == 0:
        return smallest_period
    # Otherwise, find the smallest divisor of n that is a valid rotation period
    for k in range(1, n + 1):
        if n % k == 0 and s == s[k:] + s[:k]:
            return k
    return n
