def allocate(total_cents: int, weights: list[int]) -> list[int]:
    if total_cents < 0:
        raise ValueError("total_cents must not be negative")
    if not weights:
        raise ValueError("weights must not be empty")
    if any(w < 0 for w in weights):
        raise ValueError("weights must not be negative")
    if all(w == 0 for w in weights):
        raise ValueError("weights must not all be zero")

    total = sum(weights)
    base = [total_cents * w // total for w in weights]
    remainder = [total_cents * w % total for w in weights]

    result = base[:]
    # Distribute leftover cents one each to largest remainder, ties to earliest part
