from collections import defaultdict

def build_order(deps: dict[str, list[str]]) -> list[str]:
    all_items = set(deps.keys())
    for u, ds in deps.items():
        for d in ds:
            all_items.add(d)

    remaining = {u: 0 for u in all_items}
    for u, ds in deps.items():
        remaining[u] = len(ds)

    dependents = defaultdict(list)
    for u, ds in deps.items():
        for d in ds:
            dependents[d].append(u)

    ready = [u for u in all_items if remaining[u] == 0]
    heapq.heapify(ready)

    order = []
    while ready:
        v = heapq.heappop(ready)
        order.append(v)
        for u in dependents[v]:
            remaining[u] -= 1
            if remaining[u] == 0:
                heapq.heappush(ready, u)

    if len(order) != len(all_items):
        raise ValueError("cycle detected")

    return order
