import functools

def natural_sorted(names: list[str]) -> list[str]:
    def tokenize(s: str) -> list[tuple[int, object]]:
        tokens: list[tuple[int, object]] = []
        i = 0
        n = len(s)
        while i < n:
            c = s[i]
            if c.isdigit():
                j = i
                while j < n and s[j].isdigit():
                    j += 1
                tokens.append((1, int(s[i:j])))
                i = j
            else:
                j = i
                while j < n and not s[j].isdigit():
                    j += 1
                tokens.append((0, s[i:j].lower()))
                i = j
        return tokens

    def compare(a: str, b: str) -> int:
        ta = tokenize(a)
        tb = tokenize(b)
        for x, y in zip(ta, tb):
            if x[0] != y[0]:
                return -1 if x[0] < y[0] else 1
            if x[1] != y[1]:
                return -1 if x[1] < y[1] else 1
        if len(ta) != len(tb):
            return -1 if len(ta) < len(tb) else 1
        return 0

    return functools.cmp_to_key(compare)(list(names))
